import { useCallback, useEffect, useState } from 'react'

import { TodoAlreadyCompletedError } from '../../application/TodoAlreadyCompletedError'
import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

export type TodosState =
  | { readonly status: 'loading' }
  | { readonly status: 'loaded'; readonly todos: TodoViewModel[] }
  | { readonly status: 'failed' }

export type TodosModel = {
  readonly state: TodosState
  readonly completionError: string | null
  readonly complete: (id: string) => Promise<void>
}

export const useTodos = (): TodosModel => {
  const { listTodos, completeTodo } = useTodosUseCases()
  const [state, setState] = useState<TodosState>({ status: 'loading' })
  const [completionError, setCompletionError] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()
    listTodos.execute(controller.signal).then(
      (todos) => setState({ status: 'loaded', todos }),
      () => {
        if (!controller.signal.aborted) setState({ status: 'failed' })
      },
    )
    return () => controller.abort()
  }, [listTodos])

  const complete = useCallback(
    async (id: string) => {
      setCompletionError(null)
      const markDone = (): void =>
        setState((current) =>
          current.status === 'loaded'
            ? {
                status: 'loaded',
                todos: current.todos.map((todo) => (todo.id === id ? { ...todo, status: 'done' } : todo)),
              }
            : current,
        )
      try {
        await completeTodo.execute(id)
        markDone()
      } catch (error) {
        if (error instanceof TodoAlreadyCompletedError) {
          markDone()
          setCompletionError('This todo is already completed.')
        } else {
          setCompletionError('The todo could not be completed.')
        }
      }
    },
    [completeTodo],
  )

  return { state, completionError, complete }
}
